'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var Float64Array = require( '@stdlib/array/float64' );
var uniform = require( '@stdlib/random/base/uniform' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var EPS = require( '@stdlib/constants/float64/eps' );
var pkg = require( './../package.json' ).name;
var Triangular = require( './../lib' );


// MAIN //

bench( pkg+'::instantiation', function benchmark( bm ) {
	var dist;
	var len;
	var a;
	var b;
	var c;
	var i;

	len = bm.iterations;
	a = new Float64Array( len );
	b = new Float64Array( len );
	c = new Float64Array( len );

	for ( i = 0; i < len; i++ ) {
		a[ i ] = ( uniform( 0.0, 10.0 ) ) + EPS;
		b[ i ] = ( uniform( 0.0, 10.0 ) ) + a[ i ] + EPS;
		c[ i ] = ( uniform( 0.0, ( b[ i ] - a[ i ] ) ) ) + a[ i ];
	}

	bm.tic();
	for ( i = 0; i < bm.iterations; i++ ) {
		dist = new Triangular( a[ i % len ], b[ i % len ], c[ i % len ] );
		if ( !( dist instanceof Triangular ) ) {
			bm.fail( 'should return a distribution instance' );
		}
	}
	bm.toc();
	if ( !( dist instanceof Triangular ) ) {
		bm.fail( 'should return a distribution instance' );
	}
	bm.pass( 'benchmark finished' );
	bm.end();
});

bench( pkg+'::get:a', function benchmark( bm ) {
	var dist;
	var a;
	var b;
	var c;
	var y;
	var i;

	a = 20.0;
	b = 40.0;
	c = 30.0;
	dist = new Triangular( a, b, c );

	bm.tic();
	for ( i = 0; i < bm.iterations; i++ ) {
		y = dist.a;
		if ( y !== a ) {
			bm.fail( 'should return set value' );
		}
	}
	bm.toc();
	if ( isnan( y ) ) {
		bm.fail( 'should not return NaN' );
	}
	bm.pass( 'benchmark finished' );
	bm.end();
});

bench( pkg+'::set:a', function benchmark( bm ) {
	var dist;
	var len;
	var a;
	var b;
	var c;
	var y;
	var i;

	a = 20.0;
	b = 120.0;
	c = 110.0;
	dist = new Triangular( a, b, c );

	len = bm.iterations;
	y = new Float64Array( len );
	for ( i = 0; i < len; i++ ) {
		y[ i ] = ( 100.0*uniform( 0.0, 1.0 ) ) + EPS;
	}

	bm.tic();
	for ( i = 0; i < bm.iterations; i++ ) {
		dist.a = y[ i % len ];
		if ( dist.a !== y[ i % len ] ) {
			bm.fail( 'should return set value' );
		}
	}
	bm.toc();
	if ( isnan( y[ ( i - 1 ) % len ] ) ) {
		bm.fail( 'should not return NaN' );
	}
	bm.pass( 'benchmark finished' );
	bm.end();
});

